      "rationale": "The cited spans supply comparable event recording, stage classification, group comparison, the recurrence rule, its connection to feasible trial selection, and the missingness, sparsity and inferential limits."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C038.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
